    double from = 11;
    double to = 111.5;
    double stepsize = 2.5;
    DoubleVector vec = DenseDoubleVector.fromUpTo(from, to, stepsize);
    int curIndex = 0;
    double cur = 11;
    while (cur <= to) {
        assertEquals(cur, vec.get(curIndex), 0.000001);
        cur += stepsize;
        ++curIndex;
    }
}

